body {
    color: #797979;
    font-family: Verdana;
    line-height: 3rem;
    padding: 0px !important;
    margin: 0px !important;
    text-rendering: optimizeLegibility;
    overflow-x: hidden;
    background: url("../imagine/tapiz10.jpg");
    background-size: 450px 450px;
    font-family: arial, sans-serif;
}

.load {
    position: fixed;
    left: 0px;
    top: 0px;
    width: 100%;
    height: 100%;
    z-index: 9999;
    background: url('../imagine/carga.gif') 50% 50% no-repeat #ffffff;
}
a, a:hover, a:focus, button, input, textarea, select {
    text-decoration: none;
    outline: none;
    resize: none;
    outline: none !important;
    outline-width: 0 !important;
    box-shadow: none !important;
    -moz-box-shadow: none;
    -webkit-box-shadow: none;
}
.col {
    background-image: linear-gradient(hsl(var(--hue),var(--sat),90%),hsl(var(--hue),var(--sat),75%));
    display: flex;
    flex: 1;
    padding: 1.5em 0;
    min-height: 10em;
}
.btn {
    background-color: transparent;
    background-image: linear-gradient(hsl(var(--hue),var(--sat),80%),hsl(var(--hue),var(--sat),85%));
    border-radius: 50%;
    box-shadow: 0 0 0 0.125em hsla(var(--hue),var(--sat),50%,0), 0 0 0.25em hsl(var(--hue),var(--sat),55%) inset, 0 0.125em 0.125em hsl(var(--hue),var(--sat),90%);
    cursor: pointer;
    margin: auto;
    outline: transparent;
    position: relative;
    width: 9em;
    height: 9em;
    transition: box-shadow var(--trans-dur) var(--trans-timing);
    -webkit-tap-highlight-color: transparent;
}
.btn:focus-visible {
    box-shadow: 0 0 0 0.125em hsla(var(--hue),var(--sat),50%,1), 0 0 0.25em hsl(var(--hue),var(--sat),55%) inset, 0 0.125em 0.125em hsl(var(--hue),var(--sat),90%);
}
.btn:before,
.btn:after {
    border-radius: inherit;
    content: "";
    display: block;
    position: absolute;
}
.btn:before {
    background-image: linear-gradient(hsl(var(--hue),var(--sat),90%),hsl(var(--hue),var(--sat),80%));
    box-shadow: 0 0.75em 0.75em 0.25em hsla(var(--hue2),0%,0%,0.3);
    top: 1em;
    left: 1.12em;
    width: 6.8em;
    height: 6.8em;
    transition: box-shadow var(--trans-dur) var(--trans-timing2), transform var(--trans-dur) var(--trans-timing2);
}
.btn:after {
    background-color: hsl(var(--hue),var(--sat),75%);
    background-image: linear-gradient(hsla(var(--hue),var(--sat),90%,0),hsl(var(--hue),var(--sat),90%));
    box-shadow: 0 0.0625em 0 hsl(var(--hue),var(--sat),90%) inset, 0 -0.0625em 0 hsl(var(--hue),var(--sat),90%) inset, 0 0 0 0 hsla(var(--hue),var(--sat),var(--light2),0.1) inset;
    top: 2.1em;
    left: 2.3em;
    width: 4.7em;
    height: 4.7em;
    transition: background-color var(--trans-dur) var(--trans-timing), box-shadow var(--trans-dur) var(--trans-timing), transform var(--trans-dur) var(--trans-timing2);
}
.btn__icon {
    display: block;
    position: absolute;
    top: calc(50% - 0.80em);
    left: calc(50% - 0.88em);
    width: 2em;
    height: 2em;
    transition: filter var(--trans-dur) var(--trans-timing);
    z-index: 1;
}
.btn__icon g {
    stroke: hsl(var(--hue),var(--sat),70%);
    transition: stroke var(--trans-dur) var(--trans-timing);
}
.btn__sr {
    overflow: hidden;
    position: absolute;
    width: 1px;
    height: 1px;
}
.btn[aria-pressed="true"]:before,
.btn[aria-pressed="true"]:after,
.btn[aria-pressed="true"] .btn__icon {
    transform: scale(0.98);
}
.btn[aria-pressed="true"]:before {
    box-shadow: 0 0.375em 0.375em 0 hsla(var(--hue),0%,0%,0.3);
    transition-timing-function: var(--trans-timing3);
}
.btn[aria-pressed="true"]:after {
    background-color: hsl(var(--hue),var(--sat),90%);
    box-shadow: 0 0.0625em 0 hsla(var(--hue),var(--sat),var(--light2),0.5) inset, 0 -0.0625em 0 hsla(var(--hue),var(--sat),var(--light2),0.5) inset, 0 0 0.75em 0.25em hsla(var(--hue),var(--sat),var(--light2),0.1) inset;
    transition-timing-function: var(--trans-timing), var(--trans-timing), var(--trans-timing3);
}
.btn[aria-pressed="true"] .btn__icon {
    filter: drop-shadow(0 0 0.25em var(--primary));
}
.btn[aria-pressed="true"] .btn__icon g {
    stroke: var(--primary);
}
