/* ============================================
   DATA-TITLE - TOOLTIP DEBAJO DEL ELEMENTO
   ============================================ */

/* Forzar que TODO el contenedor sea visible */
div[style*="max-height:50em"],
div[style*="max-height:50em"] table,
div[style*="max-height:50em"] table thead,
div[style*="max-height:50em"] table thead tr,
div[style*="max-height:50em"] table thead th {
    overflow: visible !important;
}

/* Reducir el z-index del encabezado */
div[style*="max-height:50em"] table thead {
    z-index: 1 !important;
}

div[style*="max-height:50em"] table thead th {
    z-index: 1 !important;
}

/* Burbuja con z-index menor */
#burbujaCedula {
    z-index: 999 !important;
}

/* ===== TOOLTIP DEBAJO DEL ELEMENTO ===== */
[data-title] {
    position: relative !important;
    display: inline-block !important;
}

[data-title]:after {
    content: attr(data-title);
    width: 10em !important;
    max-width: 250px !important;
    background-color: #ffffff !important;
    color: #333333 !important;
    font-size: 14px !important;
    font-family: verdanab !important;
    position: absolute !important;
    padding: 6px 10px !important;
    top: 100% !important;          /* ← Aparece DEBAJO */
    left: 50% !important;
    transform: translateX(-50%) !important;
    text-align: center !important;
    box-shadow: 1px 1px 3px #222222 !important;
    opacity: 0 !important;
    border: 1px solid #333333 !important;
    z-index: 99999999 !important;
    visibility: hidden !important;
    border-radius: 0 !important;
    pointer-events: none !important;
    white-space: nowrap !important;
    margin-top: 6px !important;   /* ← Separación debajo */
    transition: all 0.1s ease 0.5s !important;
}

[data-title]:hover:after {
    opacity: 1 !important;
    visibility: visible !important;
}
.alert {
    background: #ffffff;
    border-radius: 16px !important;
    width: 270px;
    color: #e7744f;
    border: 1px solid #e7744f !important;
    font-size: 14px !important;
    margin: 0;
    margin-top: -1em !important;
}
.no-scroll-y {
    overflow-y: hidden !important;
}
.prelogo {
    fill: currentColor;
    margin: 0 auto;
    position: absolute;
    color: #e5e5e5;
    left: 50%;
    top: 50%;
    margin-left: -42px;
    margin-top: -105px;
}
.ctn-preloader {
    align-items: center;
    cursor: none;
    display: flex;
    height: 100%;
    justify-content: center;
    position: fixed;
    left: 0;
    top: 6em;
    width: 100%;
    z-index: 900;
}
.ctn-preloader .animation-preloader {
    position: absolute;
    z-index: 100;
}
.ctn-preloader .animation-preloader .txt-loading {
    font-size: 2em;
    font-family: verdanab;
    text-align: center;
    user-select: none;
}
.ctn-preloader .animation-preloader .txt-loading .letters-loading:before {
    animation: letters-loading 4s infinite;
    color: #000;
    content: attr(data-text-preloader);
    left: 0;
    opacity: 0;
    position: absolute;
    transform: rotateY(-90deg);
    margin-top: 1px;
}
.ctn-preloader .animation-preloader .txt-loading .letters-loading {
    color: rgba(0, 0, 0, 0.2);
    position: relative;
}
.ctn-preloader .animation-preloader .txt-loading .letters-loading:nth-child(2):before {
    animation-delay: 0.2s;
}
.ctn-preloader .animation-preloader .txt-loading .letters-loading:nth-child(3):before {
    animation-delay: 0.4s;
}
.ctn-preloader .animation-preloader .txt-loading .letters-loading:nth-child(4):before {
    animation-delay: 0.6s;
}
.ctn-preloader .animation-preloader .txt-loading .letters-loading:nth-child(5):before {
    animation-delay: 0.8s;
}
.ctn-preloader .animation-preloader .txt-loading .letters-loading:nth-child(6):before {
    animation-delay: 1s;
}
.ctn-preloader .animation-preloader .txt-loading .letters-loading:nth-child(7):before {
    animation-delay: 1.2s;
}
.ctn-preloader .animation-preloader .txt-loading .letters-loading:nth-child(8):before {
    animation-delay: 1.4s;
}
.ctn-preloader .animation-preloader .txt-loading .letters-loading:nth-child(9):before {
    animation-delay: 1.6s;
}
.ctn-preloader .animation-preloader .txt-loading .letters-loading:nth-child(10):before {
    animation-delay: 1.8s;
}
.ctn-preloader .animation-preloader .txt-loading .letters-loading:nth-child(11):before {
    animation-delay: 1.8s;
}
.ctn-preloader .loader-section {
    height: 100%;
    position: fixed;
    top: 0;
    width: calc(50% + 1px);
}
.ctn-preloader .loader-section.section-left {
    left: 0;
}
.ctn-preloader .loader-section.section-right {
    right: 0;
}
.loaded .animation-preloader {
    opacity: 0;
    transition: 0.3s ease-out;
}
.loaded .loader-section.section-left {
    transform: translateX(-101%);
    transition: 0.7s 0.3s all cubic-bezier(0.1, 0.1, 0.1, 1.000);
}
.loaded .loader-section.section-right {
    transform: translateX(101%);
    transition: 0.7s 0.3s all cubic-bezier(0.1, 0.1, 0.1, 1.000);
}
@keyframes letters-loading {
    0%,
    75%,
    100% {
        opacity: 0;
        transform: rotateY(-90deg);
    }
    25%,
    50% {
        opacity: 1;
        transform: rotateY(0deg);
    }
}
@media screen and (max-width: 767px) {
    .ctn-preloader .animation-preloader .txt-loading {
        font: bold 3.5em 'verdanab', sans-serif;
    }
}
@media screen and (max-width: 500px) {
    .ctn-preloader .animation-preloader .txt-loading {
        font: bold 2em 'verdanab', sans-serif;
    }
}
.checkbox label {
    display: inline-block;
    position: relative;
    float: center !important;
    margin-left: 28px !important;
}
.checkbox input[type="checkbox"]:checked + label::after {
    font-family: 'FontAwesome';
    content: "\f00c";
    font-size: 26px !important;
}
#Certificada0,
#Sede0,
#Area0 {
    width: 34px;
    height: 34px;
    color: #666666;
    border: none !important;
    background: transparent !important;
    border-radius: 50% !important;
    transition: color 0.6s, opacity 0.6s linear;
}
#Certificada0:hover {
    color: #db610a;
}
#Sede0:hover {
    color: #db610a;
}
#Area0:hover {
    color: #db610a;
}
#textarea button {
