            top: 0;
            left: 0;
            width: 100%;
            height: 100%;
            background: rgba(0, 0, 0, 0.3);
            z-index: 1040;
            justify-content: flex-start;
            align-items: flex-start;
            padding-top: 80px;
        }
        .sidebar-overlay.active {
            display: flex;
        }
        /* Cuadro central - más arriba */
        .sidebar-central {
            background: white;
            width: 30em;
            max-width: 90%;
            max-height: 70vh;
            border-radius: 12px;
            padding: 25px;
            box-shadow: 0 8px 30px rgba(0,0,0,0.2);
            overflow-y: auto;
            position: relative;
            margin: 0 auto;
            animation: slideDown 0.3s ease-out;
            border: 1px solid rgba(255,255,255,0.3);
        }
        @keyframes slideDown {
            from {
                opacity: 0;
                transform: translateY(-20px);
            }
            to {
                opacity: 1;
                transform: translateY(0);
            }
        }
        /* Botón cerrar (X) */
        .btn-close-central {
            position: absolute;
            top: 12px;
            right: 15px;
