/* ============================================
   SIDEBAR OVERLAY - VENTANA MÁS ARRIBA
   ============================================ */
/* Overlay de fondo */
.sidebar-overlay {
    position: fixed;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    background: rgba(0, 0, 0, 0.5);
    z-index: 9999;
    display: none;
    justify-content: center;
    align-items: flex-start;
    padding-top: 15px;
    animation: fadeIn 0.3s ease;
}

/* Contenedor central */
.sidebar-central {
    background: #ffffff;
    width: 340px;
    max-width: 92%;
    max-height: 90vh;
    padding: 25px 20px 20px;
    position: relative;
    border-radius: 16px;
    box-shadow: 0 25px 80px rgba(0, 0, 0, 0.3);
    animation: slideInTop 0.3s ease;
    overflow-y: auto;
}

/* Botón cerrar */
.btn-close-central {
    position: absolute;
    top: 12px;
    right: 12px;
    background: #f0f2f5;
    border: none;
    border-radius: 50%;
    width: 32px;
    height: 32px;
    font-size: 18px;
    color: #666;
    cursor: pointer;
    display: flex;
    align-items: center;
    justify-content: center;
    transition: all 0.3s ease;
    z-index: 10;
}

.btn-close-central:hover {
    background: #e74c3c;
    color: #ffffff;
    transform: rotate(90deg);
}

.btn-close-central i {
    font-size: 18px;
}

/* ============================================
   MENÚ SIDEBAR - FONDO BLANCO
   ============================================ */
ul.sidebar-menu {
    list-style: none;
    padding: 0;
    margin: 0;
}

ul.sidebar-menu#nav-accordion {
    background: #ffffff !important;
}
/* Elementos principales */
ul.sidebar-menu li {
    margin-bottom: 6px;
    position: relative;
}
/* Enlaces principales */
ul.sidebar-menu li a {
    color: #333333;
    text-decoration: none;
    display: flex;
    align-items: center;
    padding: 14px 16px;
    font-size: 14px;
    font-weight: 500;
    outline: none;
    border-radius: 10px;
    transition: all 0.3s ease;
    gap: 12px;
    background: #f8f9fa;
    border: 1px solid transparent;
    cursor: pointer;
}
ul.sidebar-menu li a i {
    font-size: 18px;
    color: #555;
    width: 24px;
    text-align: center;
    transition: color 0.3s ease;
}
ul.sidebar-menu li a span {
    flex: 1;
    font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
}
/* Flecha del submenú */
ul.sidebar-menu li a .arrow-icon {
    font-size: 13px;
    color: #999;
    margin-left: auto;
    transition: transform 0.3s ease;
}
ul.sidebar-menu li a .arrow-icon.open {
    transform: rotate(180deg);
}
/* Estados hover, focus y active */
ul.sidebar-menu li a:hover,
ul.sidebar-menu li a:focus {
    background: #f2f2f2;
    color: #000000;
    border-color: 0;
    transform: translateX(4px);
}
ul.sidebar-menu li a.active {
    background: #dfddee;
    color: #000000;
    border-color: 0;
    box-shadow: 0 2px 12px rgba(139, 195, 74, 0.2);
}

ul.sidebar-menu li a:hover i,
ul.sidebar-menu li a:focus i,
ul.sidebar-menu li a.active i {
    color: #000000;
}

/* ============================================
   SUBMENÚ
   ============================================ */

ul.sidebar-menu li ul.sub {
    list-style: none;
    padding: 0;
    margin: 4px 0 0 0;
    max-height: 0;
    overflow: hidden;
    transition: max-height 0.4s ease, opacity 0.3s ease, margin 0.3s ease;
    opacity: 0;
    visibility: hidden;
}

ul.sidebar-menu li ul.sub.open {
    max-height: 400px;
    opacity: 1;
    visibility: visible;
    margin: 4px 0 0 0;
}

ul.sidebar-menu li ul.sub li {
    margin: 0;
}

ul.sidebar-menu li ul.sub li a {
    font-size: 13px;
    padding: 10px 16px 10px 54px;
    font-weight: 400;
    background: transparent;
    border: none;
    border-radius: 8px;
    color: #555;
    margin: 1px 0;
    position: relative;
    transition: all 0.3s ease;
    cursor: pointer;
}

ul.sidebar-menu li ul.sub li a::before {
    content: '';
    position: absolute;
    left: 36px;
    top: 50%;
    transform: translateY(-50%);
    width: 4px;
    height: 4px;
    background: #ccc;
    border-radius: 50%;
    transition: all 0.3s ease;
}

ul.sidebar-menu li ul.sub li a:hover {
    color: #000000;
    background: #dfddee;
    padding-left: 60px;
}

ul.sidebar-menu li ul.sub li a:hover::before {
    background: #9f99cc;
    width: 6px;
    height: 6px;
}

ul.sidebar-menu li ul.sub li a.active {
    color: #564d99;
    background: #9f99cc;
    font-weight: 600;
}

ul.sidebar-menu li ul.sub li a.active::before {
    background: #4caf50;
    width: 6px;
    height: 6px;
}

/* ============================================
   ANIMACIONES
   ============================================ */

@keyframes fadeIn {
    from {
        opacity: 0;
    }
    to {
        opacity: 1;
    }
}

@keyframes slideInTop {
    from {
        transform: translateY(-20px);
        opacity: 0;
    }
    to {
        transform: translateY(0);
        opacity: 1;
    }
}

/* ============================================
   RESPONSIVE
   ============================================ */

@media (max-width: 768px) {
    .sidebar-overlay {
        padding-top: 0;
        align-items: center;
    }

    .sidebar-central {
        width: 100%;
        max-width: 100%;
        max-height: 100vh;
        padding: 20px 16px 16px;
        border-radius: 0;
        box-shadow: none;
        animation: slideIn 0.3s ease;
    }

    .btn-close-central {
        top: 10px;
        right: 10px;
        width: 28px;
        height: 28px;
        font-size: 16px;
    }

    ul.sidebar-menu li a {
        padding: 12px 14px;
        font-size: 13px;
    }

    ul.sidebar-menu li ul.sub li a {
        padding: 8px 14px 8px 44px;
        font-size: 12px;
    }

    ul.sidebar-menu li ul.sub li a::before {
        left: 28px;
    }

    ul.sidebar-menu li ul.sub li a:hover {
        padding-left: 50px;
    }
}

@media (max-width: 480px) {
    .sidebar-central {
        padding: 16px 12px 12px;
    }

    .btn-close-central {
        top: 8px;
        right: 8px;
        width: 24px;
        height: 24px;
        font-size: 14px;
    }

    ul.sidebar-menu li a {
        padding: 10px 12px;
        font-size: 12px;
        gap: 10px;
    }

    ul.sidebar-menu li a i {
        font-size: 16px;
        width: 20px;
    }

    ul.sidebar-menu li ul.sub li a {
        padding: 6px 10px 6px 36px;
        font-size: 11px;
    }

    ul.sidebar-menu li ul.sub li a::before {
        left: 22px;
        width: 3px;
        height: 3px;
    }

    ul.sidebar-menu li ul.sub li a:hover {
        padding-left: 42px;
    }

    ul.sidebar-menu li ul.sub li a:hover::before {
        width: 4px;
        height: 4px;
    }
}

/* Animación para móviles */
@keyframes slideIn {
    from {
        transform: translateY(-30px) scale(0.96);
        opacity: 0;
