            url: "../contador_usuarios.html",
            cache: false,
            success: function (html) {
                $("#enlinea").html(html);   
              
                var newscrollHeight = $("#enlinea").prop("scrollHeight") - 20; 
                if (newscrollHeight > oldscrollHeight) {
                    $("#enlinea").animate({scrollTop: newscrollHeight}, 'normal'); 
                }
            },
        });
