    $(document).ready(function() {
        var actual = window.location+'';
        var split = actual.split("?");
        var pdf = split[split.length-1];
        if (pdf == 'pdf') {
            setTimeout(function(){
                pdf2();
                $(".loader").fadeOut("slow");
            },1000);
        };
        (function(API){
            API.myText = function(txt, options, x, y) {
                options = options ||{};
                if( options.align == "center" ){
                    var fontSize = this.internal.getFontSize();
                    var pageWidth = this.internal.pageSize.width;
                    txtWidth = this.getStringUnitWidth(txt)*fontSize/this.internal.scaleFactor;
                    x = ( pageWidth - txtWidth ) / 2;
                }
                this.text(txt,x,y);
        };
        })(jsPDF.API);
        (function(H) {
            H.Chart.prototype.createCanvas = function(divId) {
                var svg = this.getSVG(),
                    width = parseInt(svg.match(/width="([0-9]+)"/)[9]),
                    height = parseInt(svg.match(/height="([0-9]+)"/)[9]),
                    canvas = document.createElement('canvas');
                    canvas.setAttribute('width', width);
                    canvas.setAttribute('height', height);
                if (canvas.getContext && canvas.getContext('2d')) {
                    canvg(canvas, svg);
                    return canvas.toDataURL("image/png");
                }
                else {
                    alert("Your browser doesn't support this feature, please use a modern browser");
                    return false;
                }
            }
        }(Highcharts));
         //Exportar PDF        
        function pdf2() {
            var doc = new jsPDF('p', 'pt', 'letter');
            var fG = new Date();
            var fM = fG.getMonth()+1;
            var fG3 = (fG.getDate() + "/" + fM + "/" + fG.getFullYear());
            var empresa = '<?php echo $Razon ?>';
            var nit = '<?php echo $Nit ?>';

            var img = new Image()
            img.src = '../imagine/logo.png'
            doc.addImage(img, 'png', 225, 20, 160, 130)
            img.src = '../imagine/informe6.png'
            doc.addImage(img, 'png', 45, 200, 530, 22)
            doc.setFont("times");
            doc.setFontType("bold");
            doc.setTextColor(0,0,0);
            doc.setFontSize(15);
            doc.myText(empresa,{align: "center"},0,400);
            doc.setFontSize(13);
            doc.myText('NIT: '+nit,{align: "center"},0,420);
            
            switch ('<?php echo  $sede_c ?>') {
                case '1':
                         doc.myText('<?php echo $sede1 ?>',{align: "center"},0,440);
                    break;
                case '2':
                        doc.myText('<?php echo $sede1.' y '.$sede2 ?>',{align: "center"},0,440);
                    break;
                case '3':
                     doc.myText('<?php echo $sede1.', '.$sede2.' y '.$sede3 ?>',{align: "center"},0,440);
                    break;
                case '4':
                     doc.myText('<?php echo $sede1.', '.$sede2.', '.$sede3.' y '.$sede4 ?>',{align: "center"},0,440);
                    break;
                case '5':
                   doc.myText('<?php echo $sede1.', '.$sede2.', '.$sede3.', '.$sede4.' y '.$sede5 ?>',{align: "center"},0,440);
                    break;
                case '6':
                    doc.myText('<?php echo $sede1.', '.$sede2.', '.$sede3.', '.$sede4.', '.$sede5.' y '.$sede6 ?>',{align: "center"},0,440);
                    break;
                default:
                    doc.myText('<?php echo $sede1.', '.$sede2.', '.$sede3.', '.$sede4.', '.$sede5.', '.$sede6.' y '.$sede_0.' más...'?>',{align: "center"},0,440);
                    break;    
            } 
            doc.setFontSize(13);     
            doc.myText('Informe realizado por contrato de prestación de servicios',{align: "center"},0,520);
            doc.myText('Licencia Salud Ocupacional N° 201500306748',{align: "center"},0,540);
            var f = new Date();
            var f1 = f.getMonth()+1;
