            doc.text(82,440, '11. RIESGO PSICOSOCIAL EXTRALABORAL');
            doc.text(524,440, '32');
            doc.text(82,460, '12. EVALUACIÓN DEL ESTRÉS');
            doc.text(524,460, '33');
            doc.text(82,480, '13. CONCLUSIONES');
            doc.text(524,480, '34');
            doc.text(82,500, '14. PRINCIPALES INDICADORES DE RIESGO');
            doc.text(524,500, '35');
            doc.text(82,520, '15. CASOS BLANCOS Y GRUPOS FOCALES');
