     $(function () {
        var chart;
        var inputEGA  = [<?php echo $TA ?>],
        dataEGA  = [],
        categories = [''];
        $.each(inputEGA, function(index, value){
        var color;
        if (value >= 35.5) color = "#f80203";
        else if (value >= 29.6) color = "#f79729";
        else if (value >= 24.7) color = "#fffe01";
        else if (value >= 19.4) color = "#97cd53";
        else if (value >= 0)  color = "#00aff0";
        dataEGA.push({y:value, color: color, url:"https://www.perfilar.com.co"});
        });
