    myFunction();
    function myFunction() {
        if('<?php echo $Botones ?>' == 1) {
            $('.X1').show();
        }     
        if('<?php echo $Botones ?>' == '0') {
            $('.X1').hide();
        }
    };
    const toggleBtn = document.getElementById('toggleSidebarBtn');
        const overlay = document.getElementById('sidebarOverlay');
        const closeBtn = document.getElementById('closeSidebarBtn');

        // Función para abrir/cerrar
        function toggleSidebar() {
            overlay.classList.toggle('active');
        }

        // Evento clic en hamburguesa
        toggleBtn.addEventListener('click', toggleSidebar);

        // Evento clic en la X
        closeBtn.addEventListener('click', toggleSidebar);

        // Cerrar al hacer clic fuera del cuadro (en el overlay)
        overlay.addEventListener('click', function(e) {
            if (e.target === overlay) {
                toggleSidebar();
            }
        });

        // Cerrar con tecla ESC
        document.addEventListener('keydown', function(e) {
            if (e.key === 'Escape' && overlay.classList.contains('active')) {
                toggleSidebar();
            }
        });
        
        document.addEventListener('DOMContentLoaded', function () {
            // Forzar que el submenú "Consolidados" esté abierto
            var subConsolidados = document.querySelector('#nav-accordion .sub');
            if (subConsolidados) {
                subConsolidados.classList.add('open');
                subConsolidados.style.display = 'block';   // 👈 clave si el CSS usa display:none
            }
        
            // Rotar la flecha hacia arriba
            var flecha = document.querySelector('#nav-accordion .sub-menu > a .arrow-icon');
            if (flecha) {
                flecha.style.transform = 'rotate(180deg)';
                flecha.style.transition = 'transform 0.3s ease';
            }
        
            // Marcar el <li> padre como activo (opcional)
            var liPadre = document.querySelector('#nav-accordion .sub-menu');
            if (liPadre) liPadre.classList.add('active');
        });
</script>
